  const id=el.dataset.channel??el.dataset.return,track=deviceTrack(id),m=engine.mixer(id);if(!m||!track)continue;
  for(const key of ['volume','pan'])if(engine.automationActive(track,key)){const slider=el.querySelector(`[data-mix-range="${key}"]`);if(!slider)continue;slider.value=String(key==='volume'?m.gain.gain.value:m.pan.pan.value);syncMixerReadout(slider);}
