timeSelection=installTimeSelection({timeline:$('timeline'),startInput:$('time-start'),lengthInput:$('time-length'),modeButton:$('time-select-mode'),readout:$('time-selection-status'),getView:currentViewport,getTrackIds:timeScopeIds,onPan:view=>{$('timeline-start').value=view.start+1;$('timeline-bars').value=String(view.span/4);renderTimeline();renderAutomation();},isLocked:()=>!engine||engine.playing||busy||inputActive()||!!gesture||!!clipMarquee?.enabled,onChange:()=>updateLoopSelectionControl(),onStart:target=>{if(clipMarquee?.enabled)clipMarquee.disable();selectedRegion=null;if(target?.trackId)regionPasteTrack=target.trackId;updateRegionClipboardControls();suspendFollow();},onCommit:range=>{updateRegionClipboardControls();updateLoopSelectionControl();setStatus(`Selected beats ${range.start+1}–${range.start+range.length+1} for ${timeScopeLabel(timeScopeIds())}. Use Edit → Copy, Cut or Paste Time.`);}});
