async function updateLoop(next){if(engine.recording)throw new Error('Finish recording before changing the loop.');validateTransport(next);const resume=engine.playing,pos=engine.beat();if(resume)engine.pause();project.transport=next;engine.position=next.loopEnabled&&pos>=next.loopEnd?next.loopStart:pos;changed();if(resume)await engine.play(engine.mode);}
function loopSelectionRange(){const range=timeSelection?.range;if(range)return range;const regions=project?.arrangement.filter(r=>selectedRegionIds().includes(r.id))||[];if(!regions.length)return null;const start=Math.min(...regions.map(r=>r.start));return {start,length:Math.max(...regions.map(r=>r.start+r.length))-start};}
function updateLoopSelectionControl(){$('select-loop').disabled=busy||inputActive()||!!engine?.playing||!!gesture||!!timeSelection?.dragging||!!clipMarquee?.dragging;$('view-back').disabled=!selectionZoomHistory.length;const range=loopSelectionRange();$('loop-selection').disabled=view!=='arrangement'||!range||range.length<.25||range.start*4%1!==0||(range.start+range.length)*4%1!==0||range.start+range.length>16384||busy||inputActive()||!!engine?.recording||!!engine?.automationTake||!!gesture||!!timeSelection?.dragging||!!clipMarquee?.dragging;}
