function sendControls(t){return `<label>AUDIO TO<select data-output aria-label="${esc(t.name)} output" title="Post-mixer audio and destination clips are summed before destination effects.">${outputOptions(t)}</select></label>`+(project.returns||[]).map(r=>`<div class="send-control"><label>${esc(r.name)}<input type="range" min="0" max="1" step=".01" value="${t.sends?.[r.id]?.amount||0}" data-send="${esc(r.id)}" aria-label="${esc(t.name)} send to ${esc(r.name)}"></label><label class="pre-send"><input type="checkbox" data-pre="${esc(r.id)}" ${t.sends?.[r.id]?.pre?'checked':''} aria-label="${esc(t.name)} pre-fader ${esc(r.name)}">Pre-fader</label></div>`).join('');}
function renderReturns(){if(!$('returns'))return;$('returns').innerHTML=(project.returns||[]).map(r=>`<div class="channel return-channel" style="--track:${r.color}" data-return="${esc(r.id)}"><input data-return-name data-routing-structural aria-label="${esc(r.name)} name" maxlength="40" value="${esc(r.name)}"><label>VOLUME<input class="mix-value" data-mix-value="volume" aria-label="${esc(r.name)} Volume In dB" title="Enter dB, Or -inf For Silence" value="${mixerValueText('volume',r.volume)}"><input data-return-volume data-mix-range="volume" aria-valuetext="${mixerValueText('volume',r.volume)}" title="Arrow Keys: 1 dB · Shift: 0.1 dB · Double-Click: Unity" type="range" min="0" max="1" step="any" value="${r.volume}" aria-label="${esc(r.name)} volume"></label><label>PAN<input class="mix-value" data-mix-value="pan" aria-label="${esc(r.name)} Pan Value" title="C, Signed Percentage, Or 25L / 25R" value="${mixerValueText('pan',r.pan)}"><input data-return-pan data-mix-range="pan" aria-valuetext="${mixerValueText('pan',r.pan)}" title="Arrow Keys: 1% · Shift: 0.1% · Double-Click: Center" type="range" min="-1" max="1" step="any" value="${r.pan}" aria-label="${esc(r.name)} pan"></label>${crossfadeControls(r)}<div class="toggles"><button data-return-mute aria-pressed="${r.mute}" class="${r.mute?'on':''}" aria-label="Mute ${esc(r.name)}">M</button><button data-return-effects>Effects</button><button data-return-remove data-routing-structural aria-label="Remove ${esc(r.name)}"><svg class="studio-icon" width="12" height="12" viewBox="0 0 16 16" aria-hidden="true" focusable="false"><use href="#opus-icon-close"/></svg></button></div></div>`).join('')||'<p class="micro">Share a reverb or delay across tracks. Add a return, then turn up a send in the mixer.</p>';}
