$('clip-editor').addEventListener('change',run(async e=>{const key=e.target.dataset.audioEdit;if(!key)return;stopToEdit();const clip=project.clips[selection?.clipId];try{clip.audioEdit=editAudio(clip,{[key]:key==='reverse'?e.target.value==='true':Number(e.target.value)});}catch(error){renderEditor();throw error;}await engine.prepareAudioClip(clip);renderEditor();changed();}));
$('clip-editor').addEventListener('click',run(async e=>{if(e.target.id!=='reset-audio-edit')return;stopToEdit();const clip=project.clips[selection?.clipId];delete clip.audioEdit;await engine.prepareAudioClip(clip);renderEditor();changed();}));

$('clip-editor').addEventListener('click',run(async e=>{if(e.target.id!=='consolidate-region'||busy)return;stopToEdit();const originalProject=project,currentEngine=engine,regionId=selectedRegion,region=project.arrangement.find(r=>r.id===regionId),source=project.clips[region?.clipId];if(!source)return;const passage=consolidationSource(project,regionId),signature=JSON.stringify(passage.regions),sources=[...new Set(passage.regions.map(r=>r.clipId))].map(id=>{const c=project.clips[id];return {id,object:c,data:c.data,settings:JSON.stringify(c,(key,value)=>key==='data'?undefined:value)};}),bpm=project.bpm;busy=true;renderTransport();setStatus('Consolidating audio region…');try{const buffer=await engine.consolidate(regionId);if(project!==originalProject||engine!==currentEngine||engine.playing||project.bpm!==bpm||JSON.stringify(consolidationSource(project,regionId).regions)!==signature||sources.some(s=>project.clips[s.id]!==s.object||s.object.data!==s.data||JSON.stringify(s.object,(key,value)=>key==='data'?undefined:value)!==s.settings))throw new Error('The source changed during consolidation. Try again.');const result=installConsolidation(project,regionId,encode64(floatWav(buffer)));installManagedProject(result.project);engine.cacheAudio(project.clips[result.clipId],buffer);selection={trackId:region.trackId,clipId:result.clipId};selectedRegion=regionId;render();changed();setStatus(result.regionCount+' audio region'+(result.regionCount===1?'':'s')+' consolidated. Original clips retained; Undo is available.');}finally{busy=false;render();}}));

function applyMidiConsolidation(trackId,start,end){if(busy)throw new Error('Finish the current operation first.');stopToEdit();const result=consolidateMidiRange(project,trackId,start,end);installManagedProject(result.project);selection={trackId,clipId:result.clipId};selectedRegion=result.regionId;render();changed();setStatus('MIDI range consolidated. Original clips retained; Undo is available.');}
$('consolidate-midi-range').onclick=run(()=>applyMidiConsolidation($('midi-range-track').value,Number($('midi-range-start').value)-1,Number($('midi-range-end').value)-1));
