$('export-midi-arrangement').onclick=run(()=>{if($('export-source').value==='session')throw new Error('Choose Whole mix or Arrangement range, or select a MIDI clip.');return executeStudioCommand({name:'export_midi',args:readMidiDeliveryOptions()});});
