 commit:(next,observations=[],options={})=>{const preservation=options.navigationPreservation,keepSelection=preservation?.scopes.includes('selection');const live=engine.playing&&sessionActivationOnly(project,next);if(live){if(busy||inputActive()||engine.recording||engine.automationTake)throw new Error('Finish recording before changing Session activation.');const previous=project;project=next;engine.project=next;engine.syncSessionActivation(previous);renderGrid();renderEditor();changed();return;}stopToEdit();const sessionEdit=observations.filter(o=>o.type==='session_clips').at(-1);const cut=observations.filter(o=>o.type==='session_clips'&&o.clipboard).at(-1);if(!keepSelection&&sessionEdit?.selection?.length){sessionSelection=sessionEdit.selection;sessionAnchor=sessionSelection[0];selection={...sessionAnchor,clipId:sessionAnchor.clipId??null};}if(keepSelection)retainAgentSelection(preservation.expected);engine.masterVolume=next.master??.8;installManagedProject(next);if(cut)sessionClipboard=cut.clipboard;$('project-name').value=project.name;$('bpm').value=project.bpm;const noteEdit=observations.filter(o=>o.type==='midi_notes'&&o.clipId===selection?.clipId).at(-1);if(noteEdit&&!keepSelection){noteSelection=new Set(noteEdit.resultSelection);noteIndex=noteEdit.resultSelection[0]??0;const focused=project.clips[noteEdit.clipId]?.notes[noteIndex];if(focused&&(focused.pitch<noteBase||focused.pitch>noteBase+noteRange-1))noteBase=Math.max(0,Math.min(128-noteRange,focused.pitch-Math.floor((noteRange-1)/2)));renderEditor();}changed();setStatus('Agent edits applied. Undo reverses this request.');},
